BEGIN;
CREATE TABLE IF NOT EXISTS purchase_orders(id uuid PRIMARY KEY,supplier_id uuid NOT NULL REFERENCES business_partners(id),po_number varchar(80) NOT NULL UNIQUE,order_date date NOT NULL,status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','ORDERED','PARTIAL','RECEIVED','CANCELLED')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS purchase_order_items(id uuid PRIMARY KEY,purchase_order_id uuid NOT NULL REFERENCES purchase_orders(id) ON DELETE CASCADE,item_id uuid NOT NULL REFERENCES item_master(id),qty numeric(18,3) NOT NULL CHECK(qty>0),unit_price numeric(18,2) NOT NULL CHECK(unit_price>=0));
CREATE TABLE IF NOT EXISTS goods_receipts(id uuid PRIMARY KEY,purchase_order_id uuid REFERENCES purchase_orders(id),receipt_number varchar(80) NOT NULL UNIQUE,receipt_date date NOT NULL,status varchar(20) NOT NULL DEFAULT 'POSTED' CHECK(status IN('POSTED','VOID')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS goods_receipt_items(id uuid PRIMARY KEY,goods_receipt_id uuid NOT NULL REFERENCES goods_receipts(id) ON DELETE CASCADE,item_id uuid NOT NULL REFERENCES item_master(id),cycle_id uuid REFERENCES production_cycles(id),qty numeric(18,3) NOT NULL CHECK(qty>0));
CREATE TABLE IF NOT EXISTS stock_movements(id bigserial PRIMARY KEY,item_id uuid NOT NULL REFERENCES item_master(id),cycle_id uuid REFERENCES production_cycles(id),movement_type varchar(30) NOT NULL CHECK(movement_type IN('RECEIPT','ISSUE_TO_BARN','BARN_TRANSFER','ADJUSTMENT','RETURN')),qty numeric(18,3) NOT NULL,reference_type varchar(50),reference_id text,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS doc_intakes(id uuid PRIMARY KEY,cycle_id uuid NOT NULL UNIQUE REFERENCES production_cycles(id),delivered_qty integer NOT NULL CHECK(delivered_qty>=0),received_qty integer NOT NULL CHECK(received_qty>=0),doa_qty integer NOT NULL DEFAULT 0 CHECK(doa_qty>=0),strain varchar(120) NOT NULL DEFAULT '',arrival_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(received_qty<=delivered_qty));
CREATE TABLE IF NOT EXISTS daily_recordings(id uuid PRIMARY KEY,cycle_id uuid NOT NULL REFERENCES production_cycles(id),record_date date NOT NULL,age_day integer NOT NULL CHECK(age_day>=1),mortality_qty integer NOT NULL DEFAULT 0 CHECK(mortality_qty>=0),cull_qty integer NOT NULL DEFAULT 0 CHECK(cull_qty>=0),feed_used_kg numeric(18,3) NOT NULL DEFAULT 0 CHECK(feed_used_kg>=0),notes text NOT NULL DEFAULT '',UNIQUE(cycle_id,record_date));
CREATE TABLE IF NOT EXISTS body_weight_samples(id uuid PRIMARY KEY,cycle_id uuid NOT NULL REFERENCES production_cycles(id),sample_date date NOT NULL,age_day integer NOT NULL CHECK(age_day>=1),sample_qty integer NOT NULL CHECK(sample_qty>0),avg_weight_kg numeric(10,3) NOT NULL CHECK(avg_weight_kg>0));
CREATE TABLE IF NOT EXISTS medicine_usage(id uuid PRIMARY KEY,cycle_id uuid NOT NULL REFERENCES production_cycles(id),item_id uuid NOT NULL REFERENCES item_master(id),usage_date date NOT NULL,qty numeric(18,3) NOT NULL CHECK(qty>0),notes text NOT NULL DEFAULT '');
COMMIT;
